#!/usr/bin/env bash
# Chapitre « Les demandes » (partie Membres et collaboration) + sommaire.
# Prérequis : apply-espace-dossier-stable.sh.
# Usage (racine du repo) : bash apply-docs-demandes.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/membres/demandes.mdx" 2>/dev/null | grep -qF "title: \"Les demandes\""; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "Un espace a **un seul dossier pour toute sa vie**" "apps/web/content/docs/dev/membres/espaces-collaboratifs.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-espace-dossier-stable.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/index.mdx")
CREATED=("apps/web/content/docs/dev/membres/demandes.mdx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "title: \"Les demandes\"" "apps/web/content/docs/dev/membres/demandes.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/membres"
base64 -d > "apps/web/content/docs/dev/membres/demandes.mdx" <<'B64'
